function reviewKey(domain: ClinicalDisplayDomain, code: string): string {
  return `${domain}:${code.trim().toLocaleLowerCase("en")}`
}

const APPROVED_KEYS = new Set(
  APPROVED_CLINICAL_DISPLAY_TERMS.map(([domain, code]) => reviewKey(domain, code)),
)

const INTERNATIONAL_DISPLAY_DOMAINS = new Set<ClinicalDisplayDomain>([
  ...INTERNATIONAL_MEDICATION_DISPLAY_DOMAINS,
  ...INTERNATIONAL_FLUID_DISPLAY_DOMAINS,
  ...INTERNATIONAL_LAB_DISPLAY_DOMAINS,
])

export function clinicalDisplayReviewStatus(
  domain: ClinicalDisplayDomain,
  code: string,
): ClinicalDisplayReviewStatus {
  return INTERNATIONAL_DISPLAY_DOMAINS.has(domain)
    || APPROVED_KEYS.has(reviewKey(domain, code))
    ? "approved"
    : "pending"
}
